function mergeCellResponses(
  bodies: CellSearchResponse[],
  opts: {
    keywordOnly: boolean
    limit: number
    page: number
    /** True when the (single) cell already returned the requested page. */
    pagePassthrough: boolean
    /**
     * True on the no-`filter_type` path (ENT-1363): cells return per-type
     * capped lists (all tiers, tier-2 gated per type upstream), and the merge
     * re-caps per type instead of slicing one global window. Counts are then
     * derived from the merged list — "exact for what you can see" — with
     * `truncated_types`/coverage driving the "N+" lower-bound flags; the
     * cells' keyword-only count-pass fields are ignored. False preserves the
     * pre-ENT-1363 behavior for `filter_type` callers (old frontends, CLI).
     */
    perTypeCaps: boolean
    anyCellFailed: boolean
    /**
     * The advertised broad scope: index-canonical names from the BFF's own
     * PRE-filter repos snapshot, post-gate-masked per responded cell and left
     * complete for failed/unqueried/older cells. Emitted verbatim; undefined
     * (field omitted) when the index snapshot was truncated — an incomplete
     * seed must not be advertised as authoritative.
     */
    accessibleRepos: Array<{ repo: string; repo_id: string }> | undefined
    repoSetTruncated: boolean
  },
): CellSearchResponse {
  const all = bodies.flatMap((b) => b.results ?? [])

  // Each tier-0 row's rank within its own cell's tier-0 list, in the order
  // the cell returned it — the selection order sortTier0's mixed-capability
  // fallback preserves.
  const tier0CellRank = new Map<CellSearchResult, number>()
  for (const b of bodies) {
    let rank = 0
    for (const r of b.results ?? []) {
      if (r.type !== "repo" && r.searchMeta?.tier === 0) tier0CellRank.set(r, rank++)
    }
  }

  let merged: CellSearchResult[]
  if (opts.keywordOnly) {
    // Keyword-only mode is a flat BM25 ordering upstream — keep it flat here.
    merged = [...all].sort((a, b) => bm25Of(b) - bm25Of(a))
  } else if (opts.perTypeCaps) {
    // Per-type path: interleave the cells' tiered lists with the same rules
    // query-serve uses in-cell (repos, then tier 0 and tier 1 each by rerank
    // score — ENT-1431 reranks tier 0 too; see sortTier0 for the mixed-cell
    // fallback). Tier-2 (ANN-only) results no longer exist upstream
    // (entire-search#131); rows tagged tier 2 can only come from a
    // not-yet-redeployed cell and are dropped for parity.
    const repos: CellSearchResult[] = []
    const tier0: CellSearchResult[] = []
    const tier1: CellSearchResult[] = []
    for (const r of all) {
      if (r.type === "repo") repos.push(r)
      else if (r.searchMeta?.tier === 0) tier0.push(r)
      else if (r.searchMeta?.tier === 1) tier1.push(r)
    }
    repos.sort((a, b) => scoreOf(b) - scoreOf(a))
    sortTier0(tier0, tier0CellRank)
    tier1.sort((a, b) => rerankOf(b) - rerankOf(a) || scoreOf(b) - scoreOf(a))
    merged = [...repos, ...tier0, ...tier1]
  } else {
    // Legacy filter_type path (old frontends, CLI). Same tiering as above —
    // tier-2 rows from a not-yet-redeployed cell are dropped.
    const repos: CellSearchResult[] = []
    const tier0: CellSearchResult[] = []
    const tier1: CellSearchResult[] = []
    for (const r of all) {
      if (r.type === "repo") repos.push(r)
      else if (r.searchMeta?.tier === 0) tier0.push(r)
      else if (r.searchMeta?.tier === 1) tier1.push(r)
    }
    repos.sort((a, b) => scoreOf(b) - scoreOf(a))
    sortTier0(tier0, tier0CellRank)
    tier1.sort((a, b) => rerankOf(b) - rerankOf(a) || scoreOf(b) - scoreOf(a))
    merged = [...repos, ...tier0, ...tier1]
  }

  // Sessions are the one type a cell cannot speak for alone: a cross-linked
  // session (attached to repos in different cells) arrives from each of
  // them. Keep the first (highest-ranked) row per id so the list — and the
  // count derived from it — doesn't double-count. This runs on every path:
  // the filter_type page window slices the merged ordering, so a duplicate
  // surviving to the slice would render twice (and again on later pages).
  // Repo-bound types are canonical to one cell (ENT-1114) and merge without
  // dedup.
  const seenSessionIds = new Set<string>()
  let droppedSessionDupes = 0
  merged = merged.filter((r) => {
    if (r.type !== "session" || typeof r.data?.sessionId !== "string") return true
    if (seenSessionIds.has(r.data.sessionId)) {
      droppedSessionDupes++
      return false
    }
    seenSessionIds.add(r.data.sessionId)
    return true
  })

  // Per-type re-cap flags raised below; OR'd with the cells' own flags.
  const truncatedTypes: Record<string, boolean> = {}
  if (opts.perTypeCaps) {
    // Re-cap at limit per type, preserving merge order (mirrors query-serve's
    // capPerType): the union of per-cell caps can exceed the caller's limit.
    const perFacet: Record<string, number> = {}
    merged = merged.filter((r) => {
      const facet = RESULT_TYPE_TO_FACET[r.type ?? ""]
      if (!facet) return true
      perFacet[facet] = (perFacet[facet] ?? 0) + 1
      if (perFacet[facet] > opts.limit) {
        truncatedTypes[facet] = true
        return false
      }
      return true
    })
  } else {
    // Global page window. Each cell was over-fetched (page 1, limit page*limit),
    // so slicing the merged ordering here yields a true global page — no hits
    // silently dropped between per-cell pages. In pass-through mode the single
    // cell already returned the requested page: don't slice a window again.
    const start = opts.pagePassthrough ? 0 : (opts.page - 1) * opts.limit
    merged = merged.slice(start, start + opts.limit)
  }

  const counts: Record<string, number> = {}
  const fanout: Record<string, number> = {}
  let total = 0
  for (const b of bodies) {
    for (const [k, v] of Object.entries(b.fanout ?? {})) fanout[k] = (fanout[k] ?? 0) + v
    for (const [k, v] of Object.entries(b.truncated_types ?? {})) {
      if (v) truncatedTypes[k] = true
    }
  }
  const countsLowerBound: Record<string, boolean> = {}
  if (opts.perTypeCaps) {
    // Counts describe the returned list itself — the tab count can never
    // disagree with what renders. `truncated_types` (cell cap or BFF re-cap)
    // marks each floor; the cells' count-pass fields are ignored (they count
    // keyword matches only, the original ENT-1363 mismatch).
    total = merged.length
    for (const r of merged) {
      const facet = RESULT_TYPE_TO_FACET[r.type ?? ""]
      if (facet) counts[facet] = (counts[facet] ?? 0) + 1
    }
    for (const [k, v] of Object.entries(truncatedTypes)) {
      if (v) countsLowerBound[k] = true
    }
  } else {
    for (const b of bodies) {
      total += b.total ?? 0
      for (const [k, v] of Object.entries(b.counts ?? {})) counts[k] = (counts[k] ?? 0) + v
      // OR the per-facet lower-bound flag across cells: a merged facet is a
      // lower bound if any contributing cell reported its count as one
      // (entire-search#112).
      for (const [k, v] of Object.entries(b.counts_lower_bound ?? {})) {
        if (v) countsLowerBound[k] = true
      }
    }
    // Cell totals count a cross-linked session once per cell. Subtract the
    // duplicates the dedup above actually dropped so `total` doesn't send
    // paginating clients (useKeywordSearchQuery's hasNextPage) after trailing
    // pages that no longer exist. Cells over-fetch from page 1, so every
    // duplicate up to the requested window has been observed; dupes past the
    // fetched window stay counted — a bounded overcount, never an undercount.
    total = Math.max(0, total - droppedSessionDupes)
    if (droppedSessionDupes > 0 && typeof counts.sessions === "number") {
      counts.sessions = Math.max(0, counts.sessions - droppedSessionDupes)
    }
  }

  // `reranked` is honest only if EVERY cell reranked — a cell that fell back
  // to raw ANN scores doesn't share a score space with Cohere-reranked cells,
  // so a mixed interleave is degraded: flag it `partial` rather than
  // presenting a cell-blocky ordering as fully ranked.
  const anyReranked = bodies.some((b) => b.reranked === true)
  const allReranked = bodies.every((b) => b.reranked === true)
  const truncated = opts.repoSetTruncated || bodies.some((b) => b.truncated === true)
  const partial =
    truncated ||
    opts.anyCellFailed ||
    bodies.some((b) => b.partial === true) ||
    (anyReranked && !allReranked)

  // LEGACY path only: counts there are summed cell count passes, so incomplete
  // coverage genuinely makes every facet a floor — don't advertise a partial
  // sum as exact. On the per-type path this is a deliberate split of signals
  // (ENT-1363 follow-up): counts describe the returned list itself and
  // `counts_lower_bound` strictly means "this type's list was capped", while
  // coverage loss — failed cell, truncated repo set, cell-reported
  // degradation — travels on `partial` alone for consumers to surface
  // separately. Folding coverage loss back into the per-facet flags would
  // render EVERY tab as "N+" for as long as any one cell is down (the
  // ENT-1551 incident shape), collapsing the two signals the split exists to
  // distinguish.
  const coverageIncomplete =
    opts.anyCellFailed || truncated || bodies.some((b) => b.partial === true)
  if (coverageIncomplete && !opts.perTypeCaps) {
    for (const k of Object.values(RESULT_TYPE_TO_FACET)) {
      countsLowerBound[k] = true
    }
  }

  return {
    results: merged,

