func mergeSemanticV4Responses(ctx context.Context, limit, page int, results []cellCallResult[*search.Response]) (*search.Response, error) {
	if os.Getenv("ENTIRE_SEARCH_DEBUG") != "" {
		for _, r := range results {
			label := r.group.label()
			if r.err != nil {
				fmt.Fprintf(os.Stderr, "[DBG] cell=%s ERR=%v\n", label, r.err)
				continue
			}
			if r.value == nil {
				fmt.Fprintf(os.Stderr, "[DBG] cell=%s value=nil\n", label)
				continue
			}
			hist := map[string]int{}
			for _, res := range r.value.Results {
				hist[res.Type]++
			}
			fmt.Fprintf(os.Stderr, "[DBG] cell=%s Total=%d Counts=%+v rawResults=%d byType=%v reranked=%v\n",
				label, r.value.Total, r.value.Counts, len(r.value.Results), hist, r.value.Reranked)
