					fmt.Fprintf(os.Stderr, "[DBG]   session id=%q tier=%v rr=%v\n", res.ResultID(), tierOf(res), res.Meta.RerankScore)
				}
			}
		}
	}
	pages, failed, lastErr := classifySemanticCells(ctx, results)

