          return { kind: "clientError", status: mapped.status, message: mapped.message }
        }
        return { kind: "cellFailure" }
      }
      return { kind: "ok", body: (await res.json()) as CellSearchResponse }
    } catch (err) {
      console.error("[search] cell failed", cell, err instanceof Error ? err.message : err)
      return { kind: "cellFailure" }
    } finally {
      clearTimeout(timer)
    }
  }),
)

const succeeded = cellResults.flatMap((r) => (r.kind === "ok" ? [r.body] : []))

// Post-gate mask (entire-search#101): a cell that responded with its broad
// accessible_repos speaks authoritatively for ITS OWN repos — a seed entry
// homed there that the cell doesn't advertise is gated (e.g. org flag) and
// would 404 if pinned as a filter, so drop it. Failed cells, unqueried
// cells, and older query-serve (no field) leave their seed entries intact:
// silence must never narrow the scope. Names stay index-canonical so every
// offered option round-trips through slug resolution.
const cellIds = [...byCell.keys()]
const respondedScopes = new Map<string, Set<string>>()
cellResults.forEach((r, i) => {
  if (r.kind !== "ok" || !Array.isArray(r.body.accessible_repos)) return
  respondedScopes.set(
    cellIds[i],
    new Set(
      r.body.accessible_repos.flatMap((x) => (typeof x?.repo_id === "string" ? [x.repo_id] : [])),
    ),
  )
})

