+// search metadata; a later literal session upgrades only the row's richer data.
+func normalizeSemanticSessionResults(results []search.Result) ([]search.Result, int) {
+	normalized := make([]search.Result, 0, len(results))
+	sessionIndexes := make(map[string]int)
+
+	for _, result := range results {
+		switch result.Type {
+		case search.TypeCheckpoint:
+			normalized = append(normalized, result)
+			if result.Checkpoint == nil {
+				continue
+			}
+
+			projected := projectCheckpointSession(result)
+			key := semanticSessionKey(
+				projected.Session.Org,
+				projected.Session.Repo,
+				projected.Session.SessionID,
+				projected.Session.CheckpointID,
+			)
+			if _, exists := sessionIndexes[key]; exists {
+				continue
+			}
+			sessionIndexes[key] = len(normalized)
+			normalized = append(normalized, projected)
+
+		case search.TypeSession:
+			if result.Session == nil {
+				normalized = append(normalized, result)
+				continue
+			}
+
+			key := semanticSessionKey(
+				result.Session.Org,
+				result.Session.Repo,
+				result.Session.SessionID,
+				result.Session.CheckpointID,
+			)
+			if index, exists := sessionIndexes[key]; exists {
+				upgradeProjectedSession(&normalized[index], result)
+				continue
+			}
+			sessionIndexes[key] = len(normalized)
+			normalized = append(normalized, result)
+
+		default:
+			normalized = append(normalized, result)
+		}
+	}
+
+	return normalized, len(sessionIndexes)
+}
+
+func projectCheckpointSession(result search.Result) search.Result {
+	checkpoint := result.Checkpoint
+	sessionID := ""
+	if checkpoint.SessionID != nil {
+		sessionID = *checkpoint.SessionID
+	}
+
+	displayName := checkpoint.Prompt
+	if displayName == "" && checkpoint.CommitSubject != nil {
+		displayName = *checkpoint.CommitSubject
+	}
+	if displayName == "" {
+		displayName = "Untitled session"
+	}
+
+	return search.Result{
+		Type: search.TypeSession,
+		Meta: result.Meta,
+		Session: &search.SessionResult{
+			SessionID:      sessionID,
+			CheckpointID:   checkpoint.ID,
+			CommitSHA:      checkpoint.CommitSHA,
+			DisplayName:    displayName,
+			Prompt:         &checkpoint.Prompt,
+			Org:            checkpoint.Org,
+			Repo:           checkpoint.Repo,
+			Branch:         &checkpoint.Branch,
+			AuthorUsername: checkpoint.AuthorUsername,
+			CreatedAt:      checkpoint.CreatedAt,
+		},
+	}
+}
+
+func semanticSessionKey(org, repo, sessionID, checkpointID string) string {
+	if sessionID != "" {
+		return org + "\x00" + repo + "\x00" + sessionID
+	}
+	return "cp\x00" + org + "\x00" + repo + "\x00" + checkpointID
+}
+
+func upgradeProjectedSession(projected *search.Result, literal search.Result) {
+	if projected.Session == nil || literal.Session == nil {
+		return
+	}
+
+	checkpointID := projected.Session.CheckpointID
+	commitSHA := projected.Session.CommitSHA
+	branch := projected.Session.Branch
+	meta := projected.Meta
+	upgraded := *literal.Session
+	upgraded.CheckpointID = checkpointID
+	upgraded.CommitSHA = commitSHA
+	if upgraded.Branch == nil {
+		upgraded.Branch = branch
+	}
+	projected.Session = &upgraded
+	projected.Meta = meta
+}
+
 // aggregateSemanticTotals sums per-cell totals and counts, minus dedup, and
 // excluding cells whose entire page was a discarded ANN fallback — their
 // matches are unreachable, so they must not be advertised.

