  useEffect(() => {
    if (!isCodeTab || !repoStats?.length) return
    const sorted = [...repoStats].sort((a, b) => b.match_count - a.match_count)
    for (let i = 0; i < Math.min(3, sorted.length); i++) {
      const parsed = parseCodeSearchRepoName(sorted[i].repo)
      if (!parsed) continue
      queryClient.prefetchQuery(repoTreeQueryOptions(parsed.org, parsed.repo, "main"))
    }
  }, [isCodeTab, repoStats, queryClient])

  const allResults = useMemo(() => data?.results ?? [], [data?.results])
  const visibleResults = useMemo(
    () => allResults.filter((result) => !HIDDEN_SEARCH_RESULT_TYPES.has(result.type)),
    [allResults],
  )

  // Results reshaped into the row types the shared /commits and /sessions
  // list components render. The sessions rows fold in checkpoint hits (the
  // checkpoints tab is gone — a checkpoint match surfaces as its session).
  const commitRowsBase = useMemo(() => buildCommitRows(allResults), [allResults])
  const sessionRowsBase = useMemo(() => buildSessionRows(allResults), [allResults])

  // Rows lazily fill in what the index doesn't carry (checkpoint counts,
  // full session data) as they scroll into view — see the hook for the
  // mechanics and the ENT-1609 deletion plan.
  const {
    commitRows,
    sessionRows: hydratedSessionRows,
    onCommitRowVisible,
    onSessionRowVisible,
  } = useSearchRowHydration(commitRowsBase, sessionRowsBase)

  const hasActiveFilters = Boolean(
    (urlType && urlType !== "code") || selectedRepos.length > 0 || author || date || branch,
  )
  // The type tabs only render while a query is present, so a lingering
  // `types` param is invisible on the empty-query screen — don't let it
  // suppress the recents view or offer "Clear filters" for nothing.
  const hasNonTypeFilters = Boolean(selectedRepos.length > 0 || author || date || branch)
  const showFilterControls = hasQuery || hasActiveFilters

  // Tab counts are "exact for what you can see" (ENT-1363): commits straight
  // from the response counts (server-derived from the returned list), sessions
  // from the merged session+projected-checkpoint rows — the merge and dedup
  // happen client-side, so the server's per-facet counts can't describe it.
  const typeCounts = useMemo(
    () => ({
      commits: data?.counts ? (data.counts.commits ?? 0) : commitRows.length,
      sessions: hydratedSessionRows.length,
    }),
    [data?.counts, commitRows.length, hydratedSessionRows.length],
  )

  // Per-facet lower-bound flags (entire-search#112): true ⇒ the count is a floor,
  // rendered "N+". Absent reads as exact. Sessions fold in checkpoint hits, so
  // either capped facet makes the merged count a floor.
  const typeCountsLowerBound = useMemo(
    () => ({
      commits: data?.counts_lower_bound?.commits ?? false,
      sessions:
        (data?.counts_lower_bound?.sessions ?? false) ||
        (data?.counts_lower_bound?.checkpoints ?? false),
    }),
    [data?.counts_lower_bound],
  )

  const hasAnyTypeResults = typeCounts.commits + typeCounts.sessions > 0

  // Coverage was incomplete — a cell failed/timed out or the repo set was
  // truncated. With results showing this is deliberately silent: counts
  // describe exactly the list on screen. Only when the search ALSO produced
  // no results does it matter — switching tabs won't help and "no results"
  // would be a false negative, so it gets its own empty state below.
  // `coverage_incomplete`, not `partial`: partial also covers rerank-mix
  // ordering degradation, which never means a source was unavailable.
  const searchIncomplete = data?.coverage_incomplete === true
