=== types.go: response structs (SearchResult, SessionResult, CheckpointResult, Counts, SearchMeta) ===

type SearchParams struct {
	Q          string
	Types      []string // "repos", "checkpoints", "commits", "prs", "sessions"
	Repos      []string // repo filter (repo ULIDs); empty = all accessible
	Branch     string
	Author     string
	Date       string // "week" or "month"
	Page       int
	Limit      int
	PerType    PerTypeLimits
	Mode       SearchMode
	FilterType string // "checkpoints", "commits", "sessions"
}

type PerTypeLimits struct {
	Repos       int
	Checkpoints int
}

type SearchMeta struct {
	MatchType SearchMatchType `json:"matchType"`
	// Score is the retrieval score, normalized so higher is always better
	// (see CombinedScore). It is NOT the field results are ordered by: when
	// RerankScore is present the cross-encoder decided the order, and Score
	// only reports how retrieval rated the hit. Sorting by it undoes reranking.
	Score   float64    `json:"score"`
	Tier    SearchTier `json:"tier"`
	Snippet string     `json:"snippet,omitempty"`
	// RerankScore is the cross-encoder's relevance judgement, present only on
	// results that went through reranking. Where present it is the signal the
	// final ordering was built from, and the only one comparable across repos
	// — retrieval scores are computed per-namespace against per-repo corpus
	// statistics.
	RerankScore *float64 `json:"rerankScore,omitempty"`
	BM25Score   *float64 `json:"bm25Score,omitempty"`
	ANNScore    *float64 `json:"annScore,omitempty"`
	BM25Rank    *int     `json:"bm25Rank,omitempty"`
	ANNRank     *int     `json:"annRank,omitempty"`
	// Projected marks a result synthesized from another type's document (a
	// commit projected from a checkpoint hit's commit_sha) rather than a match
	// on the type's own documents. The per-type tier-2 gate must not count
	// derivative hits as keyword evidence for the type (PR #126 bugbot), and
	// the BFF's cross-cell merge gate needs the same signal (ENT-1381).
	// omitempty: absent means a real match, keeping old payloads compatible.
	Projected bool `json:"projected,omitempty"`
}

type RepoResult struct {
	ID              string  `json:"id"`
	GithubRepoID    int64   `json:"githubRepoId"`
	Org             string  `json:"org"`
	Name            string  `json:"name"`
	FullName        string  `json:"fullName"`
	Description     *string `json:"description"`
	CheckpointCount int     `json:"checkpointCount"`
}

type CheckpointResult struct {
	ID             string   `json:"id"`
	Prompt         string   `json:"prompt"`
	CommitMessage  *string  `json:"commitMessage"`
	CommitSubject  *string  `json:"commitSubject"`
	CommitSha      *string  `json:"commitSha"`
	Branch         string   `json:"branch"`
	Org            string   `json:"org"`
	Repo           string   `json:"repo"`
	Author         string   `json:"author"`
	AuthorUsername *string  `json:"authorUsername"`
	CreatedAt      string   `json:"createdAt"`
	FilesTouched   []string `json:"filesTouched"`
	// SessionID is the checkpoint's first session (from the sessions_display
	// attribute), letting clients deep-link to /session/<id>#timeline-<cpID>
	// without a live checkpoint-resolve lookup — which 404s for checkpoints on
	// condensed/unmerged branches even though their session page still works.
	// Nil for index docs that predate the attribute.
	SessionID *string `json:"sessionId"`
}

type CommitResult struct {
	ID             string  `json:"id"`
	CommitSha      string  `json:"commitSha"`
	CommitMessage  string  `json:"commitMessage"`
	CommitSubject  string  `json:"commitSubject"`
	Branch         string  `json:"branch"`
	Org            string  `json:"org"`
	Repo           string  `json:"repo"`
	Author         string  `json:"author"`
	AuthorUsername *string `json:"authorUsername"`
	CreatedAt      string  `json:"createdAt"`
	Additions      int     `json:"additions"`
	Deletions      int     `json:"deletions"`
	FilesChanged   int     `json:"filesChanged"`
	HTMLUrl        *string `json:"htmlUrl"`
}

type PRResult struct {
	ID         string  `json:"id"`
	GithubPrID int64   `json:"githubPrId"`
	Number     int     `json:"number"`
	Title      string  `json:"title"`
	HTMLUrl    *string `json:"htmlUrl"`
	State      string  `json:"state"`
	Draft      bool    `json:"draft"`
	HeadBranch *string `json:"headBranch"`
	UserLogin  *string `json:"userLogin"`
	Org        string  `json:"org"`
	Repo       string  `json:"repo"`
	CreatedAt  string  `json:"createdAt"`
	MergedAt   *string `json:"mergedAt"`
}

type SessionResult struct {
	SessionID      string  `json:"sessionId"`
	DisplayName    string  `json:"displayName"`
	Prompt         *string `json:"prompt"`
	Agent          *string `json:"agent"`
	Model          *string `json:"model"`
	StepCount      int     `json:"stepCount"`
	Org            string  `json:"org"`
	Repo           string  `json:"repo"`
	Branch         *string `json:"branch"`
	AuthorUsername *string `json:"authorUsername"`
	CreatedAt      string  `json:"createdAt"`

	// repoID is the owning repo's storage ULID, threaded from the hit so
	// hydrateSessionDisplayNames can key its per-repo resolve call. Unexported:
	// internal plumbing, never serialized.
	repoID string
}

// SearchResult is a union type represented by setting exactly one of the Data fields.
type SearchResult struct {
	Type       string      `json:"type"` // "repo", "checkpoint", "commit", "pr", "session"
	Data       interface{} `json:"data"`
	SearchMeta SearchMeta  `json:"searchMeta"`
}

type SearchTiming struct {
	TotalMs            int64  `json:"total_ms"`
	KeywordMs          *int64 `json:"keyword_ms"`
	EmbeddingMs        *int64 `json:"embedding_ms"`
	VectorMs           *int64 `json:"vector_ms"`
	RerankMs           *int64 `json:"rerank_ms"`
	FanoutMs           *int64 `json:"fanout_ms"`
	SessionHydrationMs *int64 `json:"session_hydration_ms"`
