	wantsCheckpoints := contains(types, "checkpoints")
	for _, r := range unified.results {
		if r.Type == "checkpoint" && !wantsCheckpoints {
			continue
		}
		allResults = append(allResults, r)
	}
}

// Ranking pipeline.
var finalResults []SearchResult
if isKeywordOnly {
	sort.SliceStable(allResults, func(i, j int) bool {
		return bm25ScoreOrZero(allResults[j]) < bm25ScoreOrZero(allResults[i])
	})
	finalResults = allResults
} else {
	var tier0, tier1, tier2 []SearchResult
	var repoResults []SearchResult

	for _, r := range allResults {
		if r.Type == "repo" {
			repoResults = append(repoResults, r)
			continue
		}
		switch r.SearchMeta.Tier {
		case Tier0:
			tier0 = append(tier0, r)
		case Tier1:
			tier1 = append(tier1, r)
		default:
			// Tier 2 (ANN-only: zero keyword overlap) never reaches the
			// output directly (ENT-1363 follow-up): unreranked semantic
			// residue read as noise. Instead the best few are nominated
			// into the rerank call (ENT-1432); rows the cross-encoder
			// scores at or above annAdmissionFloor are admitted as
			// ordinary tier-1, the rest dropped.
			tier2 = append(tier2, r)
		}
	}

	// Tier 0: sort by BM25 score desc.
	sort.SliceStable(tier0, func(i, j int) bool {
		a := bm25ScoreOrZero(tier0[i])
		b := bm25ScoreOrZero(tier0[j])
		return b < a
	})

	hasKeywordMatches := len(tier0) > 0
	minRelevance := 0.3
	if !hasKeywordMatches {
		minRelevance = 0.2
	}

	// Globally score-order tier 1 across all namespaces. Tier 1 is assembled
	// in repo/resolver order, so this establishes its ranking for two
	// consumers (ENT-933 F5): the reranker's candidate cap ([:200] in
	// RerankTier1) keeps the highest-scoring hits rather than the
	// earliest-ordered repos, and when reranking is disabled or a no-op the
	// final output stays score-ordered instead of resolver-ordered.
	sort.SliceStable(tier1, func(i, j int) bool {
		return tier1[j].SearchMeta.Score < tier1[i].SearchMeta.Score
	})

	// ANN nominees (ENT-1432): the highest-similarity ANN-only hits
	// (Score = 1 − cosine distance, higher better) are appended after
	// the keyword bands. They ride beyond the keyword candidate cap in
	// the rerank call — a saturated keyword slate can't starve semantic
	// recall — bounded by an absolute cap so one search can't flood the
	// Cohere call with semantic long-tail.
	sort.SliceStable(tier2, func(i, j int) bool {
		return tier2[j].SearchMeta.Score < tier2[i].SearchMeta.Score
	})
	if len(tier2) > maxANNNominees {
		tier2 = tier2[:maxANNNominees]
	}

	// Cohere rerank over both keyword bands plus ANN nominees in one
	// call (ENT-1431/ENT-1432). Tier 0 goes first so it always fits
	// inside the candidate cap; it is reordered by relevance within its
	// band but never dropped by the floor (a full-phrase match is
	// definitionally on-topic — BM25 alone ranked long transcripts by
	// term frequency, not query relevance). Tier-2 ANN nominees go
	// last; the reranker admits the best few clearing the admission
	// floor as tier-1 rows and strips the rest. Band precedence is
	// restored by partitioning the output. A nominee-only candidate set
	// (zero keyword hits) still makes the call: whatever clears the
	// floor is all the response has.
	if s.reranker != nil && len(tier0)+len(tier1)+len(tier2) > 0 {
		candidates := make([]SearchResult, 0, len(tier0)+len(tier1)+len(tier2))
		candidates = append(candidates, tier0...)
		candidates = append(candidates, tier1...)
		candidates = append(candidates, tier2...)
		rerankStart := time.Now()
		output := s.reranker.RerankTier1(ctx, params.Q, candidates, minRelevance)
		ms := time.Since(rerankStart).Milliseconds()
		rerankMs = &ms
		reranked = &output.Reranked
		tier0 = tier0[:0]
		tier1 = tier1[:0]
		for _, r := range output.Results {
			switch r.SearchMeta.Tier {
			case Tier0:
				tier0 = append(tier0, r)
			case Tier1:
				tier1 = append(tier1, r)
			default:
				// Tier-2 rows only reach here on the rerank fallback
				// path (a failed call returns the candidates unchanged,
				// unscored) — with no admission signal they must never
				// leak into the output. Admitted nominees arrive
				// retagged Tier1 above.
			}
		}
	} else if s.reranker != nil {
		// Vacuously reranked (ENT-1430): zero candidates means nothing
		// needed reranking and nothing here can break the shared Cohere
		// score space. Omitting the flag made the BFF's every-cell AND
		// drag the merged `reranked` to false whenever any cell in the
		// fan-out came back empty.
		vacuous := true
		reranked = &vacuous
	}

	finalResults = make([]SearchResult, 0, len(repoResults)+len(tier0)+len(tier1))
	finalResults = append(finalResults, repoResults...)
	finalResults = append(finalResults, tier0...)
	finalResults = append(finalResults, tier1...)
}

// Per-type counts. The checkpoint/commit/PR/session values come from the
// honest count pass launched above (a deterministic keyword + structured
// filter count, independent of this ranked/truncated window). Repos are not a
// Turbopuffer facet — they are the keyword-matched repo set assembled here,
// which is exact unless it hit its per-type cap.
countWG.Wait()
counts := facetCounts
lowerBound := facetLowerBound
for _, r := range finalResults {
	if r.Type == "repo" {
		counts.Repos++
	}
}
if cntRepos := contains(types, "repos"); cntRepos && params.PerType.Repos > 0 && counts.Repos >= params.PerType.Repos {
	lowerBound.Repos = true
}

// Record the full ranked set held in memory (ENT-1018) — before the type-tab
// filter below narrows it, so the metric reflects the actual post-ranking
// memory footprint regardless of FilterType.
if resultSetSize != nil {
	resultSetSize.Record(ctx, int64(len(finalResults)))
}

safePage := params.Page
if safePage < 1 {
	safePage = 1
}

var results []SearchResult

	var results []SearchResult
	var total int
	var truncatedTypes SearchTypeTruncated
	if params.FilterType != "" {
		// CLI/compat path (pre-ENT-1363): filter to one type, then paginate
		// with the global limit cut. Retire together with filter_type.
		typeMap := map[string]string{
			"checkpoints": "checkpoint",
			"commits":     "commit",
			"sessions":    "session",
		}
		targetType := typeMap[params.FilterType]
		filtered := make([]SearchResult, 0)
		for _, r := range finalResults {
			if r.Type == targetType {
				filtered = append(filtered, r)
			}
		}
		total = len(filtered)
		start := (safePage - 1) * params.Limit
		if start < 0 || start > total {
			// Past the end — or int overflow from an absurd page value, which
			// must clamp to an empty page rather than panic on a negative bound.
			start = total
		}
		end := start + params.Limit
		if end < start || end > total {
			end = total
		}
		results = filtered[start:end]
	} else {
		// Per-type caps (ENT-1363): keep up to Limit results per type in rank
		// order, instead of one global top-Limit cut that starves crowded
		// types. Every type tab is served from this single snapshot, so a tab
		// count derived from the list can never disagree with it; a capped
		// type is flagged in truncated_types. Page is ignored on this path —
		// there is no pagination UI, the returned window IS the viewable
		// surface.
		results, truncatedTypes = capPerType(finalResults, params.Limit)
		total = len(results)
		// Repos are retrieved pre-capped upstream (PerType.Repos is the SQL
		// LIMIT on the repo keyword search), so overflow repos never reach
		// capPerType. Propagate the upstream cap — lowerBound.Repos above uses
		// the same "hit the retrieval cap" heuristic — so a capped repos list
		// still renders "N+".
		if lowerBound.Repos {
			truncatedTypes.Repos = true
		}
	}

	// Overlay resolved session names (custom → AI generated → heuristic) onto
	// the returned window only: ranking already ran on the indexed heuristic
	// name (today's behavior either way), and hydrating pre-rank would resolve
	// names for every candidate session a broad fan-out projects — hundreds of
	// rows that the per-type cap then cuts — instead of at most Limit sessions
	// across the handful of repos that made the page.
	sessionNamesMs = s.hydrateSessionDisplayNames(ctx, caller, results)

	totalMs := time.Since(totalStart).Milliseconds()

	s.logger.Info().
		Int64("total_ms", totalMs).
		Int("results", len(results)).
		Msg("search complete")

	return &SearchResponse{
		Results:          results,
		Total:            total,
		Page:             safePage,
		Reranked:         reranked,
		Partial:          partial,
		Fanout:           fanoutStats,
		Truncated:        truncated,
		DegradedBM25Only: degradedBM25Only,
		AccessibleRepos:  responseAccessibleRepos,
		Timing: SearchTiming{
			TotalMs:            totalMs,
			EmbeddingMs:        embeddingMs,
			VectorMs:           vectorMs,
			RerankMs:           rerankMs,
			FanoutMs:           fanoutMs,
			SessionHydrationMs: sessionHydrationMs,
			SessionNamesMs:     sessionNamesMs,
		},
		Counts:           counts,
		CountsLowerBound: lowerBound,
		TruncatedTypes:   truncatedTypes,
	}, nil
}

	// SessionNamesMs is the display-name hydration phase (the per-repo
	// resolve calls to entire-api) — distinct from SessionHydrationMs, which
	// times the in-process session projection.
	SessionNamesMs *int64 `json:"session_names_ms"`
}

