	Sessions    int `json:"sessions"`
}

// SearchTypeCountsLowerBound flags, per facet, whether the matching value in
// SearchTypeCounts is a lower bound (true → the UI should render "N+") rather
// than an exact total. A facet is a lower bound when the honest count pass could
// not account for the full match set: a namespace errored or timed out, the
// per-namespace enumeration budget was exhausted before the matches ran out, or
// (for repos) the keyword match hit its per-type cap.
//
// The zero value (false) means "exact", so an absent/omitted flag safely defaults
// to exact. The flag is composable across cells: the BFF ORs it per facet, so if
// any contributing cell reports a lower bound the merged facet is a lower bound.
type SearchTypeCountsLowerBound struct {
	Repos       bool `json:"repos"`
	Checkpoints bool `json:"checkpoints"`
	Commits     bool `json:"commits"`
	PRs         bool `json:"prs"`
	Sessions    bool `json:"sessions"`
}

// SearchTypeTruncated flags, per result type, whether that type's returned
// list was capped at the per-type limit (ENT-1363): the ranked set held more
// results of that type than the response carries, so the tab count derived
// from the list is a lower bound for that type. Composable across cells: the
// BFF ORs it per type together with its own re-cap. The zero value (false)
// means "complete", so an absent flag safely defaults to complete.
type SearchTypeTruncated struct {
	Repos       bool `json:"repos"`
	Checkpoints bool `json:"checkpoints"`
	Commits     bool `json:"commits"`
	PRs         bool `json:"prs"`
	Sessions    bool `json:"sessions"`
}

// set marks the flag for a SearchResult.Type value.
func (t *SearchTypeTruncated) set(resultType string) {
	switch resultType {
	case "repo":
		t.Repos = true
	case "checkpoint":
		t.Checkpoints = true
	case "commit":
		t.Commits = true
	case "pr":
		t.PRs = true
	case "session":
		t.Sessions = true
	}
}

