package searcher

import (
	"strings"
	"time"
)

// foldCheckpointsIntoSessions rewrites a ranked result list so checkpoint hits
// surface as their owning sessions (ENT-1595), matching the web's model where a
// checkpoint match IS its session (the checkpoints tab was removed in
// entire.io #3690). Consolidating this fold in the search service lets the CLI
// and web render the same session set without each re-deriving it.
//
// It runs AFTER ranking, on the final list, so the Cohere rerank candidate pool
// — and therefore the commit/PR judged set — is byte-identical to the fold-off
// path (no per-type rerank lanes needed; the pool never changed). Because the
// pre-rerank session projection is left in place, a session that matched by its
// own title/prompt still ranks and survives as a literal session row, so the
// title signal after-rerank folding would otherwise lose is preserved.
//
// Order is preserved: each session lands at the position of its highest-ranked
// constituent — a literal (projected) session survivor, or a folded checkpoint,
// whichever ranked first. Sessions are deduped by GLOBAL session id, because a
// crosslinked session legitimately attaches to repos across cells and must be a
// single row (matching the backend's non-repo-bound session identity). A
// checkpoint with no session id (legacy/sparse index docs) folds under a
// per-checkpoint synthetic identity, REPO-QUALIFIED because checkpoint ids are
// unique only within a repo, so two repos' legacy rows never collapse.
//
// When both a literal session and its checkpoint are present, the merge keeps
// the higher-ranked row's position/SearchMeta while preserving the richer data
// of each: a literal upgrades a checkpoint-first row's session-level fields
// (name/agent/model/repoID); a checkpoint enriches a literal-first row's
// navigation anchor, but ONLY when they share a repo (a crosslinked session
// must not point a repo-a row at a repo-b checkpoint).
//
// repo, commit, and pr rows pass through untouched. Returns the folded list and
// a per-type tally OF THAT LIST (the returned_counts source).
func foldCheckpointsIntoSessions(results []SearchResult) ([]SearchResult, SearchTypeCounts) {
	folded := make([]SearchResult, 0, len(results))
	indexByKey := make(map[string]int, len(results))

	for _, r := range results {
		switch r.Type {
		case "session":
			lit, ok := r.Data.(SessionResult)
			if !ok || lit.SessionID == "" {
				// A literal session row must carry a real id; if it somehow
				// doesn't, keep it rather than risk collapsing distinct rows.
				folded = append(folded, r)
				continue
			}
			key := realSessionKey(lit.SessionID)
			if idx, exists := indexByKey[key]; exists {
				// Already emitted at a higher rank. If that row was folded from a
				// checkpoint (leaner data), upgrade it with this literal
				// session's richer session-level fields; keep its rank/anchor.
				if existing, _ := folded[idx].Data.(SessionResult); existing.CheckpointID != "" {
					upgradeSessionFromLiteral(&folded[idx], lit)
				}
				continue
			}
			indexByKey[key] = len(folded)
			folded = append(folded, r)

		case "checkpoint":
			cp, ok := r.Data.(CheckpointResult)
			if !ok {
				folded = append(folded, r) // defensive: shouldn't happen
				continue
			}
			key, session := sessionFromCheckpoint(cp)
			if idx, exists := indexByKey[key]; exists {
				// Its session already emitted at a higher rank; backfill the
				// checkpoint anchor onto that row (same-repo only) and drop this.
				enrichSessionAnchors(&folded[idx], session)
				continue
			}
			indexByKey[key] = len(folded)
			// The folded session inherits the checkpoint's final-rank position
			// and SearchMeta (RerankScore/tier/matchType/snippet) — NOT a
			// recomputed Score, which is not the post-rerank ordering signal.
			folded = append(folded, SearchResult{
				Type:       "session",
				Data:       session,
				SearchMeta: r.SearchMeta,
			})

		default:
			folded = append(folded, r) // repo, commit, pr
		}
	}

	return folded, tallyByType(folded)
}

func realSessionKey(sessionID string) string { return "s\x00" + sessionID }

func syntheticSessionKey(org, repo, cpID string) string {
	return "cp\x00" + org + "\x00" + repo + "\x00" + cpID
}

// sessionFromCheckpoint projects a checkpoint result into a session row and
// returns its dedup key. A real session id (the checkpoint's first session)
// keys globally so it merges with a literal session row of the same id and with
// the same session folded from a sibling checkpoint. A checkpoint with no
// session id — multi-session attribution is unknown, and legacy docs predate
// the attribute — folds into its FIRST session only when present; absent, it
// gets a per-checkpoint, REPO-QUALIFIED synthetic identity so two repos' legacy
// checkpoints (checkpoint ids are unique only within a repo) never collapse.
// The durable fix for multi-session attribution is a session_id per chunk row
// in the index (out of scope here).
func sessionFromCheckpoint(cp CheckpointResult) (string, SessionResult) {
	displayName := strings.TrimSpace(cp.Prompt)
	if displayName == "" && cp.CommitSubject != nil {
		displayName = strings.TrimSpace(*cp.CommitSubject)
	}
	if displayName == "" {
		displayName = "Untitled session"
	}

	prompt := cp.Prompt
	session := SessionResult{
		DisplayName:    displayName,
		Prompt:         &prompt,
		Org:            cp.Org,
		Repo:           cp.Repo,
		Branch:         &cp.Branch,
		AuthorUsername: cp.AuthorUsername,
		CreatedAt:      cp.CreatedAt,
		CheckpointID:   cp.ID,
		CommitSha:      cp.CommitSha,
		repoID:         cp.repoID, // so hydrateSessionDisplayNames can resolve the live name
	}

	if cp.SessionID != nil && *cp.SessionID != "" {
		session.SessionID = *cp.SessionID
		return realSessionKey(*cp.SessionID), session
	}
	// Legacy/sparse: no session id. The row's identity is its checkpoint
	// (CheckpointID above); SessionID stays empty. NOTE (phase 2): the cross-cell
	// dedupers in the BFF and CLI must key on sessionId FALLING BACK to
	// checkpointId before this flag is enabled in prod — an empty sessionId
	// alone collapses every legacy row into one under the current dedupers.
	return syntheticSessionKey(cp.Org, cp.Repo, cp.ID), session
}

// upgradeSessionFromLiteral overlays a literal session's richer, session-level
// fields onto a row that was folded from a checkpoint (leaner). It keeps the
// row's ranking position/SearchMeta and its checkpoint anchor; it never demotes
// a present value to an empty one.
func upgradeSessionFromLiteral(dst *SearchResult, lit SessionResult) {
	sess, ok := dst.Data.(SessionResult)
	if !ok {
		return
	}
	if strings.TrimSpace(lit.DisplayName) != "" {
		sess.DisplayName = lit.DisplayName
	}
	if lit.Prompt != nil {
		sess.Prompt = lit.Prompt
	}
	if lit.Agent != nil {
		sess.Agent = lit.Agent
	}
	if lit.Model != nil {
		sess.Model = lit.Model
	}
	if lit.StepCount != 0 {
		sess.StepCount = lit.StepCount
	}
	if lit.repoID != "" {
		sess.repoID = lit.repoID
	}
	if lit.AuthorUsername != nil && sess.AuthorUsername == nil {
		sess.AuthorUsername = lit.AuthorUsername
	}
	if lit.Branch != nil && sess.Branch == nil {
		sess.Branch = lit.Branch
	}
	dst.Data = sess
}

// enrichSessionAnchors backfills checkpoint provenance onto an already-emitted
// session row that lacks it (a literal projected survivor has no checkpoint
// anchor). It adopts the anchor ONLY when the checkpoint shares the row's repo
// — a crosslinked session spans repos, and pointing a repo-a row at a repo-b
// checkpoint would mislink navigation. It never overwrites present fields.
func enrichSessionAnchors(dst *SearchResult, from SessionResult) {
	sess, ok := dst.Data.(SessionResult)
	if !ok {
		return
	}
	if sess.Org != from.Org || sess.Repo != from.Repo {
		return // different repo: don't cross-link the anchor
	}
	if sess.CheckpointID == "" {
		sess.CheckpointID = from.CheckpointID
	}
	if sess.CommitSha == nil {
		sess.CommitSha = from.CommitSha
	}
	if sess.repoID == "" {
		sess.repoID = from.repoID
	}
	dst.Data = sess
}

// filterSessionsByAuthorDate drops folded session rows that don't satisfy an
// author/date filter, mirroring matchesAuthorDateFilter (which the pre-rerank
// session projection skips). Only session rows are inspected; other types were
// already filtered at construction. Filters in place on the folded slice.
func filterSessionsByAuthorDate(results []SearchResult, params SearchParams) []SearchResult {
	out := results[:0]
	for _, r := range results {
		if r.Type == "session" {
			if s, ok := r.Data.(SessionResult); ok && !sessionMatchesAuthorDate(s, params) {
				continue
			}
		}
		out = append(out, r)
	}
	return out
}

func sessionMatchesAuthorDate(s SessionResult, params SearchParams) bool {
	if params.Author != "" && (s.AuthorUsername == nil || *s.AuthorUsername != params.Author) {
		return false
	}
	if params.Date != "" {
		threshold := time.Now().Add(-30 * 24 * time.Hour)
		if params.Date == "week" {
			threshold = time.Now().Add(-7 * 24 * time.Hour)
		}
		t, err := time.Parse(time.RFC3339, s.CreatedAt)
		if err != nil || t.Before(threshold) {
			return false
		}
	}
	return true
}

// tallyByType counts each result type in a list — the returned_counts source,
// exact for what the response carries (distinct from the corpus match Counts).
func tallyByType(results []SearchResult) SearchTypeCounts {
	var c SearchTypeCounts
	for _, r := range results {
		switch r.Type {
		case "repo":
			c.Repos++
		case "checkpoint":
			c.Checkpoints++
		case "commit":
			c.Commits++
		case "pr":
			c.PRs++
		case "session":
			c.Sessions++
		}
	}
	return c
}

