package searcher

import (
	"context"
	"encoding/json"
	"net/http"
	"testing"
)

// TestSessionBindsToBestCarrier pins ENT-1428: a session carried by multiple
// checkpoints must be projected from its BEST-scoring carrier, not whichever
// one the namespace fan-out happened to append first. The fan-out aggregates
// hits in repos-slice order, so the weak carrier (repo one) enters the union
// before the strong carrier (repo two); before the fix, first-seen dedupe
// bound the session to the weak hit's score and snippet.
func TestSessionBindsToBestCarrier(t *testing.T) {
	sessionsDisplay := `[{"id":"s1","displayName":"investigate heap growth","prompt":"why does heap grow"}]`

	weak := checkpointRow("cp-weak", "cp-weak", "alpha service", 1, 5)
	weak["chunk_text"] = "weak carrier chunk"
	weak["sessions_display"] = sessionsDisplay

	strong := checkpointRow("cp-strong", "cp-strong", "alpha service", 2, 50)
	strong["chunk_text"] = "strong carrier chunk"
	strong["sessions_display"] = sessionsDisplay

	srv := mockTurbopufferBehavior(t, map[string]nsBehavior{
		"v4-ulid-1": {bm25Rows: []map[string]interface{}{weak}, annRows: []map[string]interface{}{}},
		"v4-ulid-2": {bm25Rows: []map[string]interface{}{strong}, annRows: []map[string]interface{}{}},
	})
	t.Cleanup(srv.Close)

	tpuf := NewTurbopufferClient("test-key", nil, noopLogger())
	tpuf.SetBaseURL(srv.URL)

	// Order-preserving reranker: every candidate scores identically, so the
	// carrier binding — not Cohere — decides what the assertions observe.
	reranker := newTestReranker(t, func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Documents []string `json:"documents"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			t.Errorf("decoding rerank request: %v", err)
			return
		}
		pairs := make([][2]float64, len(req.Documents))
		for i := range req.Documents {
			pairs[i] = [2]float64{float64(i), 0.99}
		}
		rerankReply(t, pairs...)(w, r)
	})

	svc := NewService(nil, tpuf, staticEmbedder{}, reranker, noopLogger())
	svc.SetRepoResolver(fakeV4RepoResolver{repos: []V4Repo{
		{FullName: "entirehq/one", ULID: "ulid-1"},
		{FullName: "entirehq/two", ULID: "ulid-2"},
	}})

	resp, err := svc.Search(context.Background(), "acct-1", SearchParams{
		Q: "alpha", Types: []string{"sessions"}, Mode: ModeHybrid,
		Page: 1, Limit: 100, PerType: PerTypeLimits{Checkpoints: 100},
	})
	if err != nil {
		t.Fatalf("Search: %v", err)
	}

	var sessions []SearchResult
	for _, r := range resp.Results {
		if r.Type == "session" {
			sessions = append(sessions, r)
		}
	}
	if len(sessions) != 1 {
		t.Fatalf("expected exactly 1 projected session, got %d", len(sessions))
	}

	got := sessions[0]
	if got.SearchMeta.Snippet != "strong carrier chunk" {
		t.Errorf("session bound to wrong carrier: snippet = %q, want %q",
			got.SearchMeta.Snippet, "strong carrier chunk")
	}
	if got.SearchMeta.BM25Score == nil || *got.SearchMeta.BM25Score != 50 {
		t.Errorf("session inherited wrong carrier score: bm25 = %v, want 50", got.SearchMeta.BM25Score)
	}
	data, ok := got.Data.(SessionResult)
	if !ok {
		t.Fatalf("expected SessionResult, got %T", got.Data)
	}
	if data.SessionID != "s1" {
		t.Errorf("SessionID = %q, want %q", data.SessionID, "s1")
	}
}

// TestRerankedVacuouslyTrueWithoutCandidates pins ENT-1430: a cell whose
// search produced zero keyword candidates has nothing to rerank and must
// still report reranked=true — omitting the flag made the BFF's every-cell
// AND drag the merged flag false whenever any cell in the fan-out came back
// empty. (Since ENT-1431 tier-0 is reranked too, so only a fully empty
// candidate set exercises the vacuous path.)
func TestRerankedVacuouslyTrueWithoutCandidates(t *testing.T) {
	svc := tierService(t, nsBehavior{
		bm25Rows: []map[string]interface{}{},
		annRows:  []map[string]interface{}{},
	})

	resp, err := svc.Search(context.Background(), "acct-1", SearchParams{
		Q: "alpha service", Types: []string{"checkpoints"}, Mode: ModeHybrid,
		Page: 1, Limit: 100, PerType: PerTypeLimits{Checkpoints: 100},
	})
	if err != nil {
		t.Fatalf("Search: %v", err)
	}
	if len(resp.Results) != 0 {
		t.Fatalf("expected no results, got %+v", resp.Results)
	}

