package searcher

import "testing"

func rr(v float64) *float64 { return &v }

func cpRow(id, sessionID, org, repo, prompt string, rerank float64) SearchResult {
	var sid *string
	if sessionID != "" {
		sid = &sessionID
	}
	return SearchResult{
		Type:       "checkpoint",
		Data:       CheckpointResult{ID: id, SessionID: sid, Org: org, Repo: repo, Prompt: prompt},
		SearchMeta: SearchMeta{RerankScore: rr(rerank), Tier: Tier1},
	}
}

func sessRow(sessionID, org, repo, name string, rerank float64) SearchResult {
	return SearchResult{
		Type:       "session",
		Data:       SessionResult{SessionID: sessionID, Org: org, Repo: repo, DisplayName: name},
		SearchMeta: SearchMeta{RerankScore: rr(rerank), Tier: Tier1},
	}
}

func sessionData(t *testing.T, r SearchResult) SessionResult {
	t.Helper()
	if r.Type != "session" {
		t.Fatalf("expected session row, got %q", r.Type)
	}
	s, ok := r.Data.(SessionResult)
	if !ok {
		t.Fatalf("session row Data is not SessionResult: %T", r.Data)
	}
	return s
}

func typesOf(results []SearchResult) []string {
	out := make([]string, len(results))
	for i, r := range results {
		out[i] = r.Type
	}
	return out
}

// A checkpoint hit surfaces as its session, inheriting the checkpoint's rerank
// position; the standalone checkpoint row is gone.
func TestFold_CheckpointBecomesSession(t *testing.T) {
	in := []SearchResult{cpRow("cp1", "sess-A", "o", "r", "add pin feature", 0.62)}
	out, counts := foldCheckpointsIntoSessions(in)

	if got := typesOf(out); len(got) != 1 || got[0] != "session" {
		t.Fatalf("types = %v, want [session]", got)
	}
	s := sessionData(t, out[0])
	if s.SessionID != "sess-A" || s.CheckpointID != "cp1" {
		t.Errorf("session = %+v, want sessionId=sess-A checkpointId=cp1", s)
	}
	if s.DisplayName != "add pin feature" {
		t.Errorf("displayName = %q, want the checkpoint prompt", s.DisplayName)
	}
	if out[0].SearchMeta.RerankScore == nil || *out[0].SearchMeta.RerankScore != 0.62 {
		t.Errorf("folded row must inherit the checkpoint's rerank score 0.62")
	}
	if counts.Sessions != 1 || counts.Checkpoints != 0 {
		t.Errorf("counts = %+v, want sessions=1 checkpoints=0", counts)
	}
}

// A crosslinked session (same id) reached via a literal session row in one repo
// AND a checkpoint in another must dedupe to ONE row — global identity, not
// repo-scoped (that would split a real crosslinked session in two).
func TestFold_CrosslinkedSessionDedupedGlobally(t *testing.T) {
	in := []SearchResult{
		sessRow("sess-X", "org", "repo-a", "Session X", 0.7),
		cpRow("cp1", "sess-X", "org", "repo-b", "same session, other repo", 0.4),
	}
	out, counts := foldCheckpointsIntoSessions(in)

	if counts.Sessions != 1 {
		t.Fatalf("sessions = %d, want 1 (global dedup)", counts.Sessions)
	}
	if len(out) != 1 {
		t.Fatalf("len = %d, want 1", len(out))
	}
	// The literal row (repo-a) ranked higher and keeps the slot. The checkpoint
	// is from repo-b, so its anchor must NOT be cross-linked onto the repo-a row
	// (that would mislink navigation across repos).
	s := sessionData(t, out[0])
	if s.SessionID != "sess-X" || s.Repo != "repo-a" {
		t.Errorf("row = {sessionId:%q repo:%q}, want sess-X / repo-a", s.SessionID, s.Repo)
	}
	if s.CheckpointID != "" {
		t.Errorf("cross-repo checkpoint anchor leaked: checkpointId = %q, want empty", s.CheckpointID)
	}
}

// Same-repo: a literal session and its own checkpoint dedupe to one row, and the
// checkpoint's navigation anchor IS backfilled onto the literal row.
func TestFold_SameRepoAnchorEnriched(t *testing.T) {
	in := []SearchResult{
		sessRow("sess-Y", "o", "r", "Session Y", 0.7),
		cpRow("cpY", "sess-Y", "o", "r", "same repo checkpoint", 0.4),
	}
	out, _ := foldCheckpointsIntoSessions(in)
	if len(out) != 1 {
		t.Fatalf("len = %d, want 1", len(out))
	}
	if s := sessionData(t, out[0]); s.CheckpointID != "cpY" {
		t.Errorf("same-repo anchor not enriched: checkpointId = %q, want cpY", s.CheckpointID)
	}
}

// A checkpoint that ranks above its literal session keeps the checkpoint's
// higher rank position, but is upgraded with the literal session's richer name.
func TestFold_CheckpointFirstUpgradedByLiteral(t *testing.T) {
	in := []SearchResult{
		cpRow("cpZ", "sess-Z", "o", "r", "raw first prompt", 0.9),
		sessRow("sess-Z", "o", "r", "Nicely Named Session", 0.3),
	}
	out, counts := foldCheckpointsIntoSessions(in)
	if counts.Sessions != 1 || len(out) != 1 {
		t.Fatalf("want one session row, got %d/%d", len(out), counts.Sessions)
	}
	s := sessionData(t, out[0])
	if s.DisplayName != "Nicely Named Session" {
		t.Errorf("displayName = %q, want the literal session's richer name", s.DisplayName)
	}
	if s.CheckpointID != "cpZ" {
		t.Errorf("lost checkpoint anchor: %q, want cpZ", s.CheckpointID)
	}
	if *out[0].SearchMeta.RerankScore != 0.9 {
		t.Errorf("rank = %v, want the higher checkpoint rank 0.9", *out[0].SearchMeta.RerankScore)
	}
}

// Legacy checkpoints with the SAME id in DIFFERENT repos must not collapse — the
// synthetic identity is repo-qualified.
func TestFold_LegacySameIDDifferentReposDoNotCollapse(t *testing.T) {
	in := []SearchResult{
		cpRow("dupID", "", "o", "repo-a", "legacy a", 0.6),
		cpRow("dupID", "", "o", "repo-b", "legacy b", 0.5),
	}
	_, counts := foldCheckpointsIntoSessions(in)
	if counts.Sessions != 2 {
		t.Fatalf("sessions = %d, want 2 (repo-qualified legacy identity)", counts.Sessions)
	}
}

// Two checkpoints with no session id must NOT collapse into one — each gets a
// per-checkpoint synthetic identity, and neither is dropped.
func TestFold_LegacyCheckpointsDoNotCollapse(t *testing.T) {
	in := []SearchResult{
		cpRow("cp1", "", "o", "r", "legacy one", 0.6),
		cpRow("cp2", "", "o", "r", "legacy two", 0.5),
	}
	out, counts := foldCheckpointsIntoSessions(in)

	if counts.Sessions != 2 {
		t.Fatalf("sessions = %d, want 2 (legacy rows must not collapse)", counts.Sessions)
	}
	if a, b := sessionData(t, out[0]), sessionData(t, out[1]); a.CheckpointID == b.CheckpointID {
		t.Errorf("legacy rows share checkpointId %q — identities collapsed", a.CheckpointID)
	}
}

// Two checkpoints of the SAME session dedupe to one row, kept at the higher rank.
func TestFold_MultipleCheckpointsSameSession(t *testing.T) {
	in := []SearchResult{
		cpRow("cp-hi", "sess-A", "o", "r", "higher", 0.9),
		cpRow("cp-lo", "sess-A", "o", "r", "lower", 0.3),
	}
	out, counts := foldCheckpointsIntoSessions(in)

	if counts.Sessions != 1 || len(out) != 1 {
		t.Fatalf("want a single session row, got %d results / %d sessions", len(out), counts.Sessions)
	}
	if s := sessionData(t, out[0]); s.CheckpointID != "cp-hi" {
		t.Errorf("kept checkpointId = %q, want the higher-ranked cp-hi", s.CheckpointID)
	}
	if *out[0].SearchMeta.RerankScore != 0.9 {
		t.Errorf("kept rerank = %v, want the higher 0.9", *out[0].SearchMeta.RerankScore)
	}
}

// commits, PRs and repos pass through the fold byte-identical and in order —
// the fold only ever rewrites checkpoint/session rows (proving it can't disturb
// other types; the rerank pool it runs after is likewise untouched).
func TestFold_OtherTypesUntouched(t *testing.T) {
	repo := SearchResult{Type: "repo", Data: RepoResult{ID: "R1"}, SearchMeta: SearchMeta{Score: 1}}
	commit := SearchResult{Type: "commit", Data: CommitResult{CommitSha: "abc"}, SearchMeta: SearchMeta{RerankScore: rr(0.5)}}
	pr := SearchResult{Type: "pr", Data: PRResult{ID: "PR1"}, SearchMeta: SearchMeta{RerankScore: rr(0.4)}}
	in := []SearchResult{repo, cpRow("cp1", "sess-A", "o", "r", "x", 0.45), commit, pr}

	out, counts := foldCheckpointsIntoSessions(in)

	if got := typesOf(out); len(got) != 4 || got[0] != "repo" || got[2] != "commit" || got[3] != "pr" {
		t.Fatalf("types/order = %v, want repo, session, commit, pr", got)
	}
	if out[0].Data.(RepoResult).ID != "R1" || out[2].Data.(CommitResult).CommitSha != "abc" || out[3].Data.(PRResult).ID != "PR1" {
		t.Errorf("commit/pr/repo payloads mutated by the fold")
	}
	if counts.Repos != 1 || counts.Commits != 1 || counts.PRs != 1 || counts.Sessions != 1 {
		t.Errorf("counts = %+v, want repos=1 commits=1 prs=1 sessions=1", counts)
	}
}

// Order follows the highest-ranked constituent: a session whose checkpoint
// ranked above a commit lands above that commit.
func TestFold_OrderPreserved(t *testing.T) {
	in := []SearchResult{
		cpRow("cp1", "sess-A", "o", "r", "top", 0.8),
		SearchResult{Type: "commit", Data: CommitResult{CommitSha: "c1"}, SearchMeta: SearchMeta{RerankScore: rr(0.6)}},
		cpRow("cp2", "sess-B", "o", "r", "third", 0.2),
	}
	out, _ := foldCheckpointsIntoSessions(in)
	want := []string{"session", "commit", "session"}
	for i, ty := range typesOf(out) {
		if ty != want[i] {
			t.Fatalf("order = %v, want %v", typesOf(out), want)
		}
	}
}

