// Service-level: the flag flips checkpoint rows into folded sessions end-to-end,
// populates returned_counts on the folded path, and leaves filter_type=checkpoints
// callers with raw checkpoints. Uses the same fake Turbopuffer/reranker harness
// as the session-carrier tests.
func TestSessionFold_ServiceLevel(t *testing.T) {
	newSvc := func() *Service {
		cp := checkpointRow("cp1", "cp1", "deploy the pin feature", 1, 5)
		cp["sessions_display"] = `[{"id":"sf1","displayName":"Deploy Session","prompt":"deploy it"}]`
		srv := mockTurbopufferBehavior(t, map[string]nsBehavior{
			"v4-ulid-1": {bm25Rows: []map[string]interface{}{cp}, annRows: []map[string]interface{}{}},
		})
		t.Cleanup(srv.Close)
		tpuf := NewTurbopufferClient("test-key", nil, noopLogger())
		tpuf.SetBaseURL(srv.URL)
		reranker := newTestReranker(t, func(w http.ResponseWriter, r *http.Request) {
			var req struct {
				Documents []string `json:"documents"`
			}
			if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
				t.Errorf("decoding rerank request: %v", err)
				return
			}
			pairs := make([][2]float64, len(req.Documents))
			for i := range req.Documents {
				pairs[i] = [2]float64{float64(i), 0.99}
			}
			rerankReply(t, pairs...)(w, r)
		})
		svc := NewService(nil, tpuf, staticEmbedder{}, reranker, noopLogger())
		svc.SetRepoResolver(fakeV4RepoResolver{repos: []V4Repo{{FullName: "entirehq/one", ULID: "ulid-1"}}})
		return svc
	}

	general := SearchParams{
		Q: "deploy", Types: []string{"checkpoints", "sessions"}, Mode: ModeHybrid,
		Page: 1, Limit: 100, PerType: PerTypeLimits{Checkpoints: 100},
	}

	// Flag OFF: checkpoint row present, returned_counts omitted (nil).
	off := newSvc()
	respOff, err := off.Search(context.Background(), "acct-1", general)
	if err != nil {
		t.Fatalf("off Search: %v", err)
	}
	if countType(respOff.Results, "checkpoint") == 0 {
		t.Fatalf("flag off: expected a checkpoint row, got %v", typesOf(respOff.Results))
	}
	if respOff.ReturnedCounts != nil {
		t.Errorf("flag off: returned_counts must be nil, got %+v", respOff.ReturnedCounts)
	}

	// Flag ON: the checkpoint is folded into a session; no checkpoint rows remain;
	// returned_counts describes the returned list.
	on := newSvc()
	on.SetSessionFoldEnabled(true)
	respOn, err := on.Search(context.Background(), "acct-1", general)
	if err != nil {
		t.Fatalf("on Search: %v", err)
	}
	if n := countType(respOn.Results, "checkpoint"); n != 0 {
		t.Errorf("flag on: checkpoint rows must be folded away, got %d (%v)", n, typesOf(respOn.Results))
	}
	if countType(respOn.Results, "session") == 0 {
		t.Fatalf("flag on: expected a folded session, got %v", typesOf(respOn.Results))
	}
	if respOn.ReturnedCounts == nil || respOn.ReturnedCounts.Checkpoints != 0 || respOn.ReturnedCounts.Sessions == 0 {
		t.Errorf("flag on: returned_counts = %+v, want checkpoints=0 sessions>=1", respOn.ReturnedCounts)
	}

	// filter_type=checkpoints keeps raw checkpoints even with the flag on.
	onFT := newSvc()
	onFT.SetSessionFoldEnabled(true)
	respFT, err := onFT.Search(context.Background(), "acct-1", SearchParams{
		Q: "deploy", FilterType: "checkpoints", Mode: ModeHybrid,
		Page: 1, Limit: 100, PerType: PerTypeLimits{Checkpoints: 100},
	})
	if err != nil {
		t.Fatalf("filter_type Search: %v", err)
	}
	if countType(respFT.Results, "checkpoint") == 0 {
		t.Errorf("filter_type=checkpoints must keep raw checkpoints with the fold on, got %v", typesOf(respFT.Results))
	}
	if respFT.ReturnedCounts != nil {
		t.Errorf("filter_type path must not set returned_counts, got %+v", respFT.ReturnedCounts)
	}
}
