1	// Command eval-ent1595 runs the v4 searcher in-process against prod Turbopuffer
2	// with a STATIC accessible-repo set — no entire-core, no DB, no JWT, no HTTP.
3	// Build it once per branch (baseline vs fixed) and diff the outputs.
4	//
5	// Env:
6	//
7	//	TP_KEY_FILE      (default ~/.tp-key)      Turbopuffer API key
8	//	COHERE_KEY_FILE  (default ~/.cohere-key)  Cohere API key
9	//	TP_REGION        (default aws-us-east-2)  -> https://{region}.turbopuffer.com
10	//	REPOS_JSON       (required)  [{"ulid","full_name"}, ...] accessible set
11	//	QUERIES_JSON     (required)  [{"q","note"}, ...]
12	//	LIMIT            (default 20)
13	//	OUT              (default stdout)
14	package main
15	
16	import (
17		"context"
18		"encoding/json"
19		"fmt"
20		"os"
21		"path/filepath"
22		"strings"
23		"time"
24	
25		"github.com/entirehq/entire-search/internal/embedder"
26		"github.com/entirehq/entire-search/internal/searcher"
27		"github.com/rs/zerolog"
28	)
29	
30	type repoEntry struct {
31		ULID     string `json:"ulid"`
32		FullName string `json:"full_name"`
33	}
34	
35	type queryEntry struct {
36		Q    string `json:"q"`
37		Note string `json:"note"`
38	}
39	
40	// staticResolver returns a fixed accessible-repo set, bypassing entire-core.
41	type staticResolver struct{ repos []searcher.V4Repo }
42	
43	func (r staticResolver) ResolveAccessibleRepos(_ context.Context, _ searcher.CallerIdentity, repoFilter []string) (searcher.RepoAccess, error) {
44		if len(repoFilter) == 0 {
45			return searcher.RepoAccess{Repos: r.repos, Broad: r.repos, Complete: true}, nil
46		}
47		inFilter := map[string]bool{}
48		for _, f := range repoFilter {
49			inFilter[f] = true
50		}
51		var filtered []searcher.V4Repo
52		for _, repo := range r.repos {
53			if inFilter[repo.ULID] {
54				filtered = append(filtered, repo)
55			}
56		}
57		return searcher.RepoAccess{Repos: filtered, Broad: r.repos, Complete: true}, nil
58	}
59	
60	func readKey(envVar, def string) string {
61		path := os.Getenv(envVar)
62		if path == "" {
63			home, _ := os.UserHomeDir()
64			path = filepath.Join(home, strings.TrimPrefix(def, "~/"))
65		}
66		b, err := os.ReadFile(path)
67		if err != nil {
68			fatalf("read key %s: %v", path, err)
69		}
70		return strings.TrimSpace(string(b))
71	}
72	
73	func loadJSON[T any](envVar string) []T {
74		path := os.Getenv(envVar)
75		if path == "" {
76			fatalf("%s is required", envVar)
77		}
78		b, err := os.ReadFile(path)
79		if err != nil {
80			fatalf("read %s: %v", path, err)
81		}
82		var out []T
83		if err := json.Unmarshal(b, &out); err != nil {
84			fatalf("parse %s: %v", path, err)
85		}
86		return out
87	}
88	
89	func fatalf(f string, a ...any) { fmt.Fprintf(os.Stderr, f+"\n", a...); os.Exit(1) }
90	
91	func deref(s *string) string {
92		if s == nil {
93			return ""
94		}
95		return *s
96	}
97	
98	// extract pulls repo/title/branch out of a SearchResult's typed Data.
99	func extract(r searcher.SearchResult) (repo, title, branch string) {
100		switch d := r.Data.(type) {
101		case searcher.CheckpointResult:
102			repo, branch = d.Repo, d.Branch
103			if d.CommitSubject != nil {
104				title = *d.CommitSubject
105			} else {
106				title = d.Prompt
107			}
108		case searcher.CommitResult:
109			repo, branch, title = d.Repo, d.Branch, d.CommitSubject
110		case searcher.SessionResult:
111			repo, branch, title = d.Repo, deref(d.Branch), d.DisplayName
112		}
113		return repo, title, branch
114	}
115	
116	type resultRow struct {
117		Type   string  `json:"type"`
118		Repo   string  `json:"repo"`
119		Title  string  `json:"title"`
120		Tier   int     `json:"tier"`
121		Score  float64 `json:"score"`
122		Branch string  `json:"branch"`
123	}
124	
125	type queryResult struct {
126		Q       string      `json:"q"`
127		Note    string      `json:"note"`
128		Total   int         `json:"total"`
129		Counts  any         `json:"counts"`
130		Results []resultRow `json:"results"`
131		Err     string      `json:"err,omitempty"`
132	}
133	
134	func main() {
135		tpKey := readKey("TP_KEY_FILE", "~/.tp-key")
136		cohereKey := readKey("COHERE_KEY_FILE", "~/.cohere-key")
137		region := os.Getenv("TP_REGION")
138		if region == "" {
139			region = "aws-us-east-2"
140		}
141		limit := 20
142		if v := os.Getenv("LIMIT"); v != "" {
143			fmt.Sscanf(v, "%d", &limit)
144		}
145	
146		repos := loadJSON[repoEntry]("REPOS_JSON")
147		queries := loadJSON[queryEntry]("QUERIES_JSON")
148	
149		v4repos := make([]searcher.V4Repo, len(repos))
150		for i, r := range repos {
151			v4repos[i] = searcher.V4Repo{ULID: r.ULID, FullName: r.FullName}
152		}
153	
154		logger := zerolog.Nop()
155		emb := embedder.New(cohereKey)
156		tpuf := searcher.NewTurbopufferClient(tpKey, emb, logger)
157		tpuf.SetBaseURL(fmt.Sprintf("https://%s.turbopuffer.com", region))
158		reranker := searcher.NewReranker(cohereKey, logger)
159		svc := searcher.NewService(nil, tpuf, emb, reranker, logger)
160		svc.SetRepoResolver(staticResolver{repos: v4repos})
161	
162		fmt.Fprintf(os.Stderr, "eval: %d repos, %d queries, region=%s, limit=%d\n", len(v4repos), len(queries), region, limit)
163	
164		var out []queryResult
165		for _, q := range queries {
166			ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
