// Command eval-ent1595 runs the v4 searcher in-process against prod Turbopuffer
// with a STATIC accessible-repo set — no entire-core, no DB, no JWT, no HTTP.
// Build it once per branch (baseline vs fixed) and diff the outputs.
//
// Env:
//
//	TP_KEY_FILE      (default ~/.tp-key)      Turbopuffer API key
//	COHERE_KEY_FILE  (default ~/.cohere-key)  Cohere API key
//	TP_REGION        (default aws-us-east-2)  -> https://{region}.turbopuffer.com
//	REPOS_JSON       (required)  [{"ulid","full_name"}, ...] accessible set
//	QUERIES_JSON     (required)  [{"q","note"}, ...]
//	LIMIT            (default 20)
//	OUT              (default stdout)
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entirehq/entire-search/internal/embedder"
	"github.com/entirehq/entire-search/internal/searcher"
	"github.com/rs/zerolog"
)

type repoEntry struct {
	ULID     string `json:"ulid"`
	FullName string `json:"full_name"`
}

type queryEntry struct {
	Q    string `json:"q"`
	Note string `json:"note"`
}

// staticResolver returns a fixed accessible-repo set, bypassing entire-core.
type staticResolver struct{ repos []searcher.V4Repo }

func (r staticResolver) ResolveAccessibleRepos(_ context.Context, _ searcher.CallerIdentity, repoFilter []string) (searcher.RepoAccess, error) {
	if len(repoFilter) == 0 {
		return searcher.RepoAccess{Repos: r.repos, Broad: r.repos, Complete: true}, nil
	}
	inFilter := map[string]bool{}
	for _, f := range repoFilter {
		inFilter[f] = true
	}
	var filtered []searcher.V4Repo
	for _, repo := range r.repos {
		if inFilter[repo.ULID] {
			filtered = append(filtered, repo)
		}
	}
	return searcher.RepoAccess{Repos: filtered, Broad: r.repos, Complete: true}, nil
}

func readKey(envVar, def string) string {
	path := os.Getenv(envVar)
	if path == "" {
		home, _ := os.UserHomeDir()
		path = filepath.Join(home, strings.TrimPrefix(def, "~/"))
	}
	b, err := os.ReadFile(path)
	if err != nil {
		fatalf("read key %s: %v", path, err)
	}
	return strings.TrimSpace(string(b))
}

func loadJSON[T any](envVar string) []T {
	path := os.Getenv(envVar)
	if path == "" {
		fatalf("%s is required", envVar)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		fatalf("read %s: %v", path, err)
	}
	var out []T
	if err := json.Unmarshal(b, &out); err != nil {
		fatalf("parse %s: %v", path, err)
	}
	return out
}

func fatalf(f string, a ...any) { fmt.Fprintf(os.Stderr, f+"\n", a...); os.Exit(1) }

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

// extract pulls repo/title/branch out of a SearchResult's typed Data.
func extract(r searcher.SearchResult) (repo, title, branch string) {
	switch d := r.Data.(type) {
	case searcher.CheckpointResult:
		repo, branch = d.Repo, d.Branch
		if d.CommitSubject != nil {
			title = *d.CommitSubject
		} else {
			title = d.Prompt
		}
	case searcher.CommitResult:
		repo, branch, title = d.Repo, d.Branch, d.CommitSubject
	case searcher.SessionResult:
		repo, branch, title = d.Repo, deref(d.Branch), d.DisplayName
	}
	return repo, title, branch
}

type resultRow struct {
	Type   string  `json:"type"`
	Repo   string  `json:"repo"`
	Title  string  `json:"title"`
	Tier   int     `json:"tier"`
	Score  float64 `json:"score"`
	Branch string  `json:"branch"`
}

type queryResult struct {
	Q       string      `json:"q"`
	Note    string      `json:"note"`
	Total   int         `json:"total"`
	Counts  any         `json:"counts"`
	Results []resultRow `json:"results"`
	Err     string      `json:"err,omitempty"`
}

func main() {
	tpKey := readKey("TP_KEY_FILE", "~/.tp-key")
	cohereKey := readKey("COHERE_KEY_FILE", "~/.cohere-key")
	region := os.Getenv("TP_REGION")
	if region == "" {
		region = "aws-us-east-2"
	}
	limit := 20
	if v := os.Getenv("LIMIT"); v != "" {
		fmt.Sscanf(v, "%d", &limit)
	}

	repos := loadJSON[repoEntry]("REPOS_JSON")
	queries := loadJSON[queryEntry]("QUERIES_JSON")

	v4repos := make([]searcher.V4Repo, len(repos))
	for i, r := range repos {
		v4repos[i] = searcher.V4Repo{ULID: r.ULID, FullName: r.FullName}
	}

	logger := zerolog.Nop()
	emb := embedder.New(cohereKey)
	tpuf := searcher.NewTurbopufferClient(tpKey, emb, logger)
	tpuf.SetBaseURL(fmt.Sprintf("https://%s.turbopuffer.com", region))
	reranker := searcher.NewReranker(cohereKey, logger)
	svc := searcher.NewService(nil, tpuf, emb, reranker, logger)
	svc.SetRepoResolver(staticResolver{repos: v4repos})

	fmt.Fprintf(os.Stderr, "eval: %d repos, %d queries, region=%s, limit=%d\n", len(v4repos), len(queries), region, limit)

	var out []queryResult
	for _, q := range queries {
		ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
		resp, err := svc.Search(ctx, "eval-account", searcher.SearchParams{
			Q:       q.Q,
			Types:   []string{"checkpoints", "commits", "sessions"},
			Mode:    searcher.ModeHybrid,
			Page:    1,
			Limit:   limit,
			PerType: searcher.PerTypeLimits{Checkpoints: limit},
		})
		cancel()
		qr := queryResult{Q: q.Q, Note: q.Note}
		if err != nil {
			qr.Err = err.Error()
			out = append(out, qr)
			fmt.Fprintf(os.Stderr, "  %q ERR: %v\n", q.Q, err)
			continue
		}
		qr.Total = resp.Total
		qr.Counts = resp.Counts
		for _, r := range resp.Results {
			repo, title, branch := extract(r)
			qr.Results = append(qr.Results, resultRow{
				Type:   r.Type,
				Repo:   repo,
				Title:  title,
				Tier:   int(r.SearchMeta.Tier),
				Score:  r.SearchMeta.Score,
				Branch: branch,
			})
		}
		out = append(out, qr)
		fmt.Fprintf(os.Stderr, "  %q -> total=%d results=%d\n", q.Q, resp.Total, len(qr.Results))
	}

	enc, _ := json.MarshalIndent(out, "", "  ")
	if outPath := os.Getenv("OUT"); outPath != "" {
		_ = os.WriteFile(outPath, enc, 0o644)
		fmt.Fprintf(os.Stderr, "wrote %s\n", outPath)
	} else {
		fmt.Println(string(enc))
	}
}

#!/usr/bin/env python3
"""N-way backend-blind nDCG@10 over a query set. Backends via PFX-<name>.json."""
import json, os, math, urllib.request, hashlib, sys
HOME=os.path.expanduser("~"); D=f"{HOME}/.claude/tmp/ent-1595/evals"
API_KEY=open(f"{HOME}/.anthropic-key").read().strip(); MODEL=os.getenv("MODEL","claude-opus-4-8")
PFX=os.getenv("PFX","starve"); NAMES=["baseline","halved","fullsplit","deep"]
BE={n:{x["q"]:x for x in json.load(open(f"{D}/{PFX}-{n}.json"))} for n in NAMES}
def key(r): return (r["type"],r["repo"],r["title"],r["branch"])
def call(query,items):
    lines=[f'[{i}] type={it["type"]} repo={it["repo"]} branch={it["branch"]} title={it["title"]!r}' for i,it in enumerate(items)]
    p=(f"Grading search results for a developer-history search engine (checkpoints=AI coding sessions, commits=git commits, sessions=grouped checkpoints).\n\nQuery: {query!r}\n\nRate each result 0-3 (3=directly answers,2=clearly relevant,1=marginal,0=irrelevant). Judge on merits.\n\nResults:\n"+"\n".join(lines)+'\n\nReturn ONLY JSON mapping index(string) to integer score.')
    body=json.dumps({"model":MODEL,"max_tokens":1600,"messages":[{"role":"user","content":p}]}).encode()
    req=urllib.request.Request("https://api.anthropic.com/v1/messages",data=body,headers={"x-api-key":API_KEY,"anthropic-version":"2023-06-01","content-type":"application/json"})
    t=json.load(urllib.request.urlopen(req,timeout=120))["content"][0]["text"].strip(); a,b=t.find("{"),t.rfind("}")
    return {int(k):int(v) for k,v in json.loads(t[a:b+1]).items()}
def dcg(r): return sum((2**x-1)/math.log2(i+2) for i,x in enumerate(r))
def ndcg(o,al,k=10): idcg=dcg(sorted(al,reverse=True)[:k]); return dcg(o[:k])/idcg if idcg>0 else 0.0
rows=[]
for q in BE["baseline"]:
    tops={n:BE[n][q]["results"][:10] for n in NAMES}
    pool,seen=[],set()
    for n in NAMES:
        for r in tops[n]:
            if key(r) not in seen: seen.add(key(r)); pool.append(r)
    order=sorted(range(len(pool)),key=lambda i:hashlib.md5((q+str(key(pool[i]))).encode()).hexdigest())
    sh=[pool[i] for i in order]; sc=call(q,sh); rel={key(sh[p]):s for p,s in sc.items()}
    allr=list(rel.values()); cs_all=[rel[key(r)] for r in pool if r["type"] in("checkpoint","session")]
    row={"q":q}
    for n in NAMES:
        row[f"nd_{n}"]=ndcg([rel[key(r)] for r in tops[n]],allr)
        row[f"cs_{n}"]=ndcg([rel[key(r)] for r in tops[n] if r["type"] in("checkpoint","session")],cs_all)
    rows.append(row); print(f"  {q[:44]:44} "+" ".join(f"{n[:4]}={row['nd_'+n]:.2f}" for n in NAMES),file=sys.stderr)
def avg(k): return sum(r[k] for r in rows)/len(rows)
print("| query | "+" | ".join(f"{n}" for n in NAMES)+" |")
print("|---|"+"|".join("---" for _ in NAMES)+"|")
for r in rows: print(f"| {r['q'][:46]} | "+" | ".join(f"{r['nd_'+n]:.3f}" for n in NAMES)+" |")
print("| **MEAN nDCG@10** | "+" | ".join(f"**{avg('nd_'+n):.3f}**" for n in NAMES)+" |")
print("| **MEAN ckpt+sess** | "+" | ".join(f"**{avg('cs_'+n):.3f}**" for n in NAMES)+" |")
json.dump(rows,open(f"{D}/judgeN-{PFX}.json","w"),indent=2)

