// the offline eval harness (ENT-1595): it lets the eval run ONE retrieval and
// derive both the unfolded and folded views from the exact same results, so a
// fold-off-vs-fold-on comparison isolates the fold from retrieval variance. Not
// used in production request handling (Search folds inline behind the flag).
func FoldForEval(results []SearchResult) []SearchResult {
	folded, _ := foldCheckpointsIntoSessions(results)
	return folded
}

