// (ENT-1595), so the eval applies the REAL cap at the REAL stage: off =
// CapPerTypeForEval(final), on = CapPerTypeForEval(FoldForEval(final)). Not used
// in production request handling.
func CapPerTypeForEval(results []SearchResult, limit int) []SearchResult {
	capped, _ := capPerType(results, limit)
	return capped
}

