toolUseResult.originalFile:
// Command eval-fold runs the v4 searcher in-process against prod Turbopuffer
// with a STATIC accessible-repo set (no core/DB/JWT), and for each query emits
// BOTH the unfolded and the folded view from the SAME retrieval — so a
// fold-off-vs-fold-on comparison isolates the checkpoint→session fold from
// retrieval variance (ENT-1595 eval).
//
// Env:
//
//	TP_KEY_FILE      (default ~/.tp-key)      Turbopuffer API key
//	COHERE_KEY_FILE  (default ~/.cohere-key)  Cohere API key
//	TP_REGION        (default aws-us-east-2)
//	REPOS_JSON       (required)  [{"ulid","full_name"}, ...]
//	QUERIES_JSON     (required)  [{"q","note"}, ...]
//	LIMIT            (default 20)
//	OUT_OFF          (default fold-off.json)  unfolded view
//	OUT_ON           (default fold-on.json)   folded view
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entirehq/entire-search/internal/embedder"
	"github.com/entirehq/entire-search/internal/searcher"
	"github.com/rs/zerolog"
)

type repoEntry struct {
	ULID     string `json:"ulid"`
	FullName string `json:"full_name"`
}

type queryEntry struct {
	Q    string `json:"q"`
	Note string `json:"note"`
}

type staticResolver struct{ repos []searcher.V4Repo }

func (r staticResolver) ResolveAccessibleRepos(_ context.Context, _ searcher.CallerIdentity, repoFilter []string) (searcher.RepoAccess, error) {
	if len(repoFilter) == 0 {
		return searcher.RepoAccess{Repos: r.repos, Broad: r.repos, Complete: true}, nil
	}
	inFilter := map[string]bool{}
	for _, f := range repoFilter {
		inFilter[f] = true
	}
	var filtered []searcher.V4Repo
	for _, repo := range r.repos {
		if inFilter[repo.ULID] {
			filtered = append(filtered, repo)
		}
	}
	return searcher.RepoAccess{Repos: filtered, Broad: r.repos, Complete: true}, nil
}

func readKey(envVar, def string) string {
	path := os.Getenv(envVar)
	if path == "" {
		home, _ := os.UserHomeDir()
		path = filepath.Join(home, strings.TrimPrefix(def, "~/"))
	}
	b, err := os.ReadFile(path)
	if err != nil {
		fatalf("read key %s: %v", path, err)
	}
	return strings.TrimSpace(string(b))
}

func loadJSON[T any](envVar string) []T {
	path := os.Getenv(envVar)
	if path == "" {
		fatalf("%s is required", envVar)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		fatalf("read %s: %v", path, err)
	}
	var out []T
	if err := json.Unmarshal(b, &out); err != nil {
		fatalf("parse %s: %v", path, err)
	}
	return out
}

func fatalf(f string, a ...any) { fmt.Fprintf(os.Stderr, f+"\n", a...); os.Exit(1) }

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func extract(r searcher.SearchResult) (repo, title, branch string) {
	switch d := r.Data.(type) {
	case searcher.CheckpointResult:
		repo, branch = d.Repo, d.Branch
		if d.CommitSubject != nil {
			title = *d.CommitSubject
		} else {
			title = d.Prompt
		}
	case searcher.CommitResult:
		repo, branch, title = d.Repo, d.Branch, d.CommitSubject
	case searcher.SessionResult:
		repo, branch, title = d.Repo, deref(d.Branch), d.DisplayName
	}
	return repo, title, branch
}

type resultRow struct {
	Type         string  `json:"type"`
	Repo         string  `json:"repo"`
	Title        string  `json:"title"`
	Tier         int     `json:"tier"`
	Score        float64 `json:"score"`
	Branch       string  `json:"branch"`
	Snippet      string  `json:"snippet"`
	SessionID    string  `json:"sessionId"`
	CheckpointID string  `json:"checkpointId"`
	CommitSha    string  `json:"commitSha"`
}

// entityIDs pulls the stable identifiers the entity-aware judge canonicalizes
// on — so a checkpoint and its folded session map to the SAME entity.
func entityIDs(r searcher.SearchResult) (sessionID, checkpointID, commitSha string) {
	switch d := r.Data.(type) {
	case searcher.CheckpointResult:
		checkpointID = d.ID
		if d.SessionID != nil {
			sessionID = *d.SessionID
		}
		if d.CommitSha != nil {
			commitSha = *d.CommitSha
		}
	case searcher.SessionResult:
		sessionID = d.SessionID
		checkpointID = d.CheckpointID
		if d.CommitSha != nil {
			commitSha = *d.CommitSha
		}
	case searcher.CommitResult:
		commitSha = d.CommitSha
	}
	return
}

type queryResult struct {
	Q       string      `json:"q"`
	Note    string      `json:"note"`
	Total   int         `json:"total"`
	Results []resultRow `json:"results"`
	Err     string      `json:"err,omitempty"`
}

func rowsFrom(results []searcher.SearchResult) []resultRow {
	rows := make([]resultRow, 0, len(results))
	for _, r := range results {
		repo, title, branch := extract(r)
		sid, cid, sha := entityIDs(r)
		rows = append(rows, resultRow{
			Type:         r.Type,
			Repo:         repo,
			Title:        title,
			Tier:         int(r.SearchMeta.Tier),
			Score:        r.SearchMeta.Score,
			Branch:       branch,
			Snippet:      r.SearchMeta.Snippet,
			SessionID:    sid,
			CheckpointID: cid,
			CommitSha:    sha,
		})
	}
	return rows
}

func writeOut(env, def string, v any) {
	path := os.Getenv(env)
	if path == "" {
		path = def
	}
	enc, _ := json.MarshalIndent(v, "", "  ")
	_ = os.WriteFile(path, enc, 0o644)
	fmt.Fprintf(os.Stderr, "wrote %s\n", path)
}

func main() {
	tpKey := readKey("TP_KEY_FILE", "~/.tp-key")
	cohereKey := readKey("COHERE_KEY_FILE", "~/.cohere-key")
	region := os.Getenv("TP_REGION")
	if region == "" {
		region = "aws-us-east-2"
	}
	limit := 20
	if v := os.Getenv("LIMIT"); v != "" {
		fmt.Sscanf(v, "%d", &limit)
	}

	repos := loadJSON[repoEntry]("REPOS_JSON")
	queries := loadJSON[queryEntry]("QUERIES_JSON")

	v4repos := make([]searcher.V4Repo, len(repos))
	for i, r := range repos {
		v4repos[i] = searcher.V4Repo{ULID: r.ULID, FullName: r.FullName}
	}

	logger := zerolog.Nop()
	emb := embedder.New(cohereKey)
	tpuf := searcher.NewTurbopufferClient(tpKey, emb, logger)
	tpuf.SetBaseURL(fmt.Sprintf("https://%s.turbopuffer.com", region))
	reranker := searcher.NewReranker(cohereKey, logger)
	svc := searcher.NewService(nil, tpuf, emb, reranker, logger)
	svc.SetRepoResolver(staticResolver{repos: v4repos})
	// One retrieval per query with the fold OFF; the eval hook captures the
	// post-rerank, PRE-cap ranked list. Both views are then derived from that
	// SAME list with the REAL production functions: off = cap(list),
	// on = cap(fold(list)) — same input, real code, real stage, no variance.
	var captured []searcher.SearchResult
	svc.SetEvalFinalResultsHook(func(r []searcher.SearchResult) { captured = r })

	fmt.Fprintf(os.Stderr, "eval: %d repos, %d queries, region=%s, limit=%d (variance-free: one retrieval, two views)\n", len(v4repos), len(queries), region, limit)

	var off, on []queryResult
	for _, q := range queries {
		captured = nil
		ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
		_, err := svc.Search(ctx, "eval-account", searcher.SearchParams{
			Q:       q.Q,
			Types:   []string{"checkpoints", "commits", "sessions"},
			Mode:    searcher.ModeHybrid,
			Page:    1,
			Limit:   limit,
			PerType: searcher.PerTypeLimits{Checkpoints: limit},
		})
		cancel()
		if err != nil {
			off = append(off, queryResult{Q: q.Q, Note: q.Note, Err: err.Error()})
			on = append(on, queryResult{Q: q.Q, Note: q.Note, Err: err.Error()})
			fmt.Fprintf(os.Stderr, "  %q ERR: %v\n", q.Q, err)
			continue
		}
		// Both views from the SAME pre-cap ranked list, via the real production
		// cap/fold: off = cap(list), on = cap(fold(list)).
		offRows := rowsFrom(searcher.CapPerTypeForEval(captured, limit))
		onRows := rowsFrom(searcher.CapPerTypeForEval(searcher.FoldForEval(captured), limit))
		off = append(off, queryResult{Q: q.Q, Note: q.Note, Total: len(offRows), Results: offRows})
		on = append(on, queryResult{Q: q.Q, Note: q.Note, Total: len(onRows), Results: onRows})
		fmt.Fprintf(os.Stderr, "  %q -> off=%d on=%d\n", q.Q, len(offRows), len(onRows))
	}

	writeOut("OUT_OFF", "fold-off.json", off)
	writeOut("OUT_ON", "fold-on.json", on)
}

