it("dedupes cross-linked sessions by id across cells, keeping the highest-ranked row (ENT-1363)", async () => {
  listReposIndex.mockResolvedValue({
    repos: [
      indexRow(REPO_ULID, "acme/backend", "aws-us-east-2", "us"),
      indexRow(REPO_ULID_2, "acme/frontend", "aws-eu-west-1", "eu"),
    ],
    truncated: false,
  })
  const mk = (entries: Array<[string, number]>) => ({
    results: entries.map(([id, score]) => ({
      type: "session",
      // Session payloads carry `sessionId`, not `id` (searcher types.go).
      data: { sessionId: id },
      searchMeta: { tier: 1, score },
    })),
    total: entries.length,
    truncated_types: {},
  })
  const fetchMock = vi.fn().mockImplementation((rawUrl: string) => {
    const cell = new URL(rawUrl).hostname.split(".")[0]
    // A session cross-linked to repos in both cells arrives from each.
    const body =
      cell === "aws-us-east-2"
        ? mk([
            ["shared", 0.9],
            ["us-only", 0.5],
          ])
        : mk([
            ["shared", 0.8],
            ["eu-only", 0.3],
          ])
    return Promise.resolve(
      new Response(JSON.stringify(body), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    )
  })
  vi.stubGlobal("fetch", fetchMock)

  const res = await sessionReq("/?q=auth")
  expect(res.status).toBe(200)
  const body = (await res.json()) as {
    results: Array<{ data: { sessionId: string } }>
    total: number
    counts: Record<string, number>
  }
  expect(body.results.map((r) => r.data.sessionId)).toEqual(["shared", "us-only", "eu-only"])
  expect(body.total).toBe(3)
  expect(body.counts).toEqual({ sessions: 3 })
})

