})

it("dedupes server-folded legacy sessions by checkpointId when sessionId is empty (ENT-1595)", async () => {
  listReposIndex.mockResolvedValue({
    repos: [
      indexRow(REPO_ULID, "acme/backend", "aws-us-east-2", "us"),
      indexRow(REPO_ULID_2, "acme/frontend", "aws-eu-west-1", "eu"),
    ],
    truncated: false,
  })
  // A checkpoint with no session id (legacy index doc) folds into a session
  // row with an EMPTY sessionId and a real checkpointId.
  const legacy = (cid: string, score: number) => ({
    type: "session",
    data: { sessionId: "", checkpointId: cid },
    searchMeta: { tier: 1, score },
  })
  const fetchMock = vi.fn().mockImplementation((rawUrl: string) => {
    const cell = new URL(rawUrl).hostname.split(".")[0]
    const body =
      cell === "aws-us-east-2"
        ? { results: [legacy("cp-shared", 0.9), legacy("cp-us", 0.5)], total: 2, truncated_types: {} }
        : { results: [legacy("cp-shared", 0.8), legacy("cp-eu", 0.3)], total: 2, truncated_types: {} }
    return Promise.resolve(
      new Response(JSON.stringify(body), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    )
  })
  vi.stubGlobal("fetch", fetchMock)

  const res = await sessionReq("/?q=auth")
  expect(res.status).toBe(200)
  const body = (await res.json()) as {
    results: Array<{ data: { checkpointId: string } }>
    total: number
  }
  // cp-shared arrives from both cells → deduped by checkpointId; cp-us/cp-eu
  // stay. Crucially the DISTINCT empty-sessionId rows are NOT collapsed into
  // one (the pre-ENT-1595 dedupe keyed on "" and would return a single row).
  expect(body.results.map((r) => r.data.checkpointId)).toEqual(["cp-shared", "cp-us", "cp-eu"])
  expect(body.total).toBe(3)
})

