package searcher

import (
	"context"
	"encoding/json"
	"net/http"
	"testing"
)

// TestSessionBindsToBestCarrier pins ENT-1428: a session carried by multiple
// checkpoints must be projected from its BEST-scoring carrier, not whichever
// one the namespace fan-out happened to append first. The fan-out aggregates
// hits in repos-slice order, so the weak carrier (repo one) enters the union
// before the strong carrier (repo two); before the fix, first-seen dedupe
// bound the session to the weak hit's score and snippet.
func TestSessionBindsToBestCarrier(t *testing.T) {
	sessionsDisplay := `[{"id":"s1","displayName":"investigate heap growth","prompt":"why does heap grow"}]`

	weak := checkpointRow("cp-weak", "cp-weak", "alpha service", 1, 5)
	weak["chunk_text"] = "weak carrier chunk"
	weak["sessions_display"] = sessionsDisplay

	strong := checkpointRow("cp-strong", "cp-strong", "alpha service", 2, 50)
	strong["chunk_text"] = "strong carrier chunk"
	strong["sessions_display"] = sessionsDisplay

	srv := mockTurbopufferBehavior(t, map[string]nsBehavior{
		"v4-ulid-1": {bm25Rows: []map[string]interface{}{weak}, annRows: []map[string]interface{}{}},
		"v4-ulid-2": {bm25Rows: []map[string]interface{}{strong}, annRows: []map[string]interface{}{}},
	})
	t.Cleanup(srv.Close)

	tpuf := NewTurbopufferClient("test-key", nil, noopLogger())
	tpuf.SetBaseURL(srv.URL)

	// Order-preserving reranker: every candidate scores identically, so the
	// carrier binding — not Cohere — decides what the assertions observe.
	reranker := newTestReranker(t, func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Documents []string `json:"documents"`
		}
